window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cc6ec4c8bc77e253"]={"versions": [{"id": "FIG-cc6ec4c8bc77e253", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Initialization</code>) zur Initialisierungsphase des AUTOSAR Watchdog Managers (<code>WdgM</code>) im Kontext der Basissoftware (BSW). Das Diagramm illustriert das Zusammenspiel zwischen dem ECU State Manager (<code>:EcuM</code>), dem Watchdog Manager (<code>:WdgM</code>), dem General Purpose Timer Driver (<code>:Gpt</code>), dem Watchdog Driver (<code>:Wdg</code>) sowie den hardwarenahen Instanzen <code>Timer Hardware</code> und <code>Watchdog Hardware</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>:EcuM</code> (ECU State Manager, Steuerungsinstanz der Startphase)</li>\n<li><code>:WdgM</code> (Watchdog Manager BSW-Modul)</li>\n<li><code>:Gpt</code> (General Purpose Timer Driver)</li>\n<li><code>Timer Hardware</code> (zugeordnete Hardware-Timer-Einheit)</li>\n<li><code>:Wdg</code> (Watchdog Driver)</li>\n<li><code>Watchdog Hardware</code> (physischer Hardware-Watchdog)</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen / Nachrichten:</p>\n<ul class=\"fig-list\">\n<li><code>Gpt_Init(ConfigPtr)</code> / Rückkehr</li>\n<li><code>Initialize Hardware</code></li>\n<li><code>Wdg_Init(ConfigPtr)</code> / Rückkehr</li>\n<li><code>Initialize and Start Hardware Watchdog</code></li>\n<li><code>WdgM_Init(ConfigPtr)</code> / Rückkehr</li>\n<li>Interner Aufruf / Selbstaufruf <code>WdgM_SetMode(return,Mode)</code></li>\n<li><code>Gpt_EnableNotification(channel)</code> / Rückkehr</li>\n<li><code>Gpt_StartTimer(channel,value)</code> / Rückkehr</li>\n<li><code>WdgM_UpdateAliveCounter(return,SEId)</code> / Rückkehr</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>:EcuM</code> ruft synchron <code>Gpt_Init(ConfigPtr)</code> am <code>:Gpt</code> auf; dieser stößt <code>Initialize Hardware</code> auf <code>Timer Hardware</code> an und kehrt zu <code>:EcuM</code> zurück.</li>\n<li><code>:EcuM</code> ruft synchron <code>Wdg_Init(ConfigPtr)</code> am <code>:Wdg</code> auf; dieser führt <code>Initialize and Start Hardware Watchdog</code> auf <code>Watchdog Hardware</code> aus und kehrt zu <code>:EcuM</code> zurück.</li>\n<li><code>:EcuM</code> initialisiert den Watchdog Manager über <code>WdgM_Init(ConfigPtr)</code>.</li>\n<li>Innerhalb von <code>WdgM_Init</code> triggert <code>:WdgM</code> einen internen Aufruf <code>WdgM_SetMode(return,Mode)</code>. Im Rahmen dieser Modusumschaltung ruft <code>:WdgM</code> synchron <code>Gpt_EnableNotification(channel)</code> und anschließend <code>Gpt_StartTimer(channel,value)</code> am <code>:Gpt</code> auf. Ein gestrichelter Rücksprung schließt den Moduswechsel innerhalb von <code>:WdgM</code> ab, gefolgt von der Rückkehr von <code>WdgM_Init</code> zu <code>:EcuM</code>.</li>\n<li><code>:EcuM</code> führt abschließend einen synchronen Aufruf <code>WdgM_UpdateAliveCounter(return,SEId)</code> am <code>:WdgM</code> aus, der quittiert wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Initialisierungsreihenfolge: Zuerst GPT und WDG initialisieren und starten, bevor die Initialisierung von <code>WdgM</code> erfolgt.</li>\n<li>Für die zyklische Triggerung gilt gemäß Kommentar-Notiz: „The GPT channel must be configured to continuous mode!“.</li>\n<li>Der Initialisierungsablauf von <code>WdgM</code> schließt das Setzen des Betriebsmodus sowie das Aktivieren und Starten des zugehörigen GPT-Kanals ein.</li>\n<li>Parameter und Rückgabewerte sind abstrakt formuliert (<code>ConfigPtr</code>, <code>return</code>, <code>Mode</code>, <code>channel</code>, <code>value</code>, <code>SEId</code>).</li>\n</ul>"}, {"id": "FIG-17392d16d4c40393", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd WdgM_Initialization</code>) zur Initialisierungsphase des AUTOSAR Watchdog Managers (<code>WdgM</code>) im Kontext der Basissoftware (BSW). Das Diagramm illustriert das Zusammenspiel zwischen dem ECU State Manager (<code>:EcuM</code>), dem Watchdog Manager (<code>:WdgM</code>), dem General Purpose Timer Driver (<code>:Gpt</code>), dem Watchdog Driver (<code>:Wdg</code>) sowie den hardwarenahen Instanzen <code>Timer Hardware</code> und <code>Watchdog Hardware</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Lebenslinien und Schnittstellen:</p>\n<ul class=\"fig-list\">\n<li><code>:EcuM</code> (ECU State Manager, Steuerungsinstanz der Startphase)</li>\n<li><code>:WdgM</code> (Watchdog Manager BSW-Modul)</li>\n<li><code>:Gpt</code> (General Purpose Timer Driver)</li>\n<li><code>Timer Hardware</code> (zugeordnete Hardware-Timer-Einheit)</li>\n<li><code>:Wdg</code> (Watchdog Driver)</li>\n<li><code>Watchdog Hardware</code> (physischer Hardware-Watchdog)</li>\n</ul>\n<p class=\"fig-p\">Aufgerufene Schnittstellen / Nachrichten mit C-Datentypen:</p>\n<ul class=\"fig-list\">\n<li><code>Gpt_Init(const Gpt_ConfigType*)</code> / Rückkehr</li>\n<li><code>Initialize Hardware()</code></li>\n<li><code>Wdg_Init(const Wdg_ConfigType*)</code> / Rückkehr</li>\n<li><code>Initialize and Start Hardware Watchdog()</code></li>\n<li><code>WdgM_Init(const WdgM_ConfigType*)</code> / Rückkehr</li>\n<li>Interner Aufruf / Selbstaufruf <code>WdgM_SetMode(Std_ReturnType, WdgM_ModeType)</code></li>\n<li><code>Gpt_EnableNotification(Gpt_ChannelType)</code> / Rückkehr</li>\n<li><code>Gpt_StartTimer(Gpt_ChannelType, Gpt_ValueType)</code> / Rückkehr</li>\n<li><code>WdgM_UpdateAliveCounter(Std_ReturnType, WdgM_SupervisedEntityIdType)</code> / Rückkehr</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><code>:EcuM</code> ruft synchron <code>Gpt_Init(ConfigPtr)</code> am <code>:Gpt</code> auf; dieser stößt <code>Initialize Hardware</code> auf <code>Timer Hardware</code> an und kehrt zu <code>:EcuM</code> zurück.</li>\n<li><code>:EcuM</code> ruft synchron <code>Wdg_Init(ConfigPtr)</code> am <code>:Wdg</code> auf; dieser führt <code>Initialize and Start Hardware Watchdog</code> auf <code>Watchdog Hardware</code> aus und kehrt zu <code>:EcuM</code> zurück.</li>\n<li><code>:EcuM</code> initialisiert den Watchdog Manager über <code>WdgM_Init(ConfigPtr)</code>.</li>\n<li>Innerhalb von <code>WdgM_Init</code> triggert <code>:WdgM</code> einen internen Aufruf <code>WdgM_SetMode(return,Mode)</code>. Im Rahmen dieser Modusumschaltung ruft <code>:WdgM</code> synchron <code>Gpt_EnableNotification(channel)</code> und anschließend <code>Gpt_StartTimer(channel,value)</code> am <code>:Gpt</code> auf. Ein gestrichelter Rücksprung schließt den Moduswechsel innerhalb von <code>:WdgM</code> ab, gefolgt von der Rückkehr von <code>WdgM_Init</code> zu <code>:EcuM</code>.</li>\n<li><code>:EcuM</code> führt abschließend einen synchronen Aufruf <code>WdgM_UpdateAliveCounter(return,SEId)</code> am <code>:WdgM</code> aus, der quittiert wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Verbindliche Initialisierungsreihenfolge: Zuerst GPT und WDG initialisieren und starten, bevor die Initialisierung von <code>WdgM</code> erfolgt.</li>\n<li>Für die zyklische Triggerung gilt gemäß Kommentar-Notiz: „The GPT channel must be configured to continuous mode!“.</li>\n<li>Der Initialisierungsablauf von <code>WdgM</code> schließt das Setzen des Betriebsmodus sowie das Aktivieren und Starten des zugehörigen GPT-Kanals ein.</li>\n<li>Formale Spezifikation der AUTOSAR-Standardtypen in den API-Signaturen (<code>const Gpt_ConfigType<em></code>, <code>const Wdg_ConfigType</em></code>, <code>const WdgM_ConfigType*</code>, <code>Std_ReturnType</code>, <code>WdgM_ModeType</code>, <code>Gpt_ChannelType</code>, <code>Gpt_ValueType</code>, <code>WdgM_SupervisedEntityIdType</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-cc6ec4c8bc77e253", "to": "FIG-17392d16d4c40393", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><strong>Diagrammkopf</strong>: Umbenannt von <code>sd Initialization</code> zu <code>sd WdgM_Initialization</code>.</li>\n<li><strong>Aufruf <code>Gpt_Init</code></strong>: Signatur von <code>Gpt_Init(ConfigPtr)</code> präzisiert zu <code>Gpt_Init(const Gpt_ConfigType*)</code>.</li>\n<li><strong>Hardware-Aktion GPT</strong>: <code>Initialize Hardware</code> um Funktionsklammern ergänzt zu <code>Initialize Hardware()</code>.</li>\n<li><strong>Aufruf <code>Wdg_Init</code></strong>: Signatur von <code>Wdg_Init(ConfigPtr)</code> präzisiert zu <code>Wdg_Init(const Wdg_ConfigType*)</code>.</li>\n<li><strong>Hardware-Aktion Wdg</strong>: <code>Initialize and Start Hardware Watchdog</code> um Funktionsklammern ergänzt zu <code>Initialize and Start Hardware Watchdog()</code>.</li>\n<li><strong>Aufruf <code>WdgM_Init</code></strong>: Signatur von <code>WdgM_Init(ConfigPtr)</code> präzisiert zu <code>WdgM_Init(const WdgM_ConfigType*)</code>.</li>\n<li><strong>Aufruf <code>WdgM_SetMode</code></strong>: Parameterangabe von <code>(return,Mode)</code> typisiert zu <code>(Std_ReturnType, WdgM_ModeType)</code>.</li>\n<li><strong>Aufruf <code>Gpt_EnableNotification</code></strong>: Parameter von <code>(channel)</code> typisiert zu <code>(Gpt_ChannelType)</code>.</li>\n<li><strong>Aufruf <code>Gpt_StartTimer</code></strong>: Parameter von <code>(channel,value)</code> typisiert zu <code>(Gpt_ChannelType, Gpt_ValueType)</code>.</li>\n<li><strong>Aufruf <code>WdgM_UpdateAliveCounter</code></strong>: Parameterangabe von <code>(return,SEId)</code> typisiert zu <code>(Std_ReturnType, WdgM_SupervisedEntityIdType)</code>.</li>\n</ul>"}]};
